const m = $json.message || {};
const texto = String(m.text || m.caption || '').trim();
const sys = "Clasificador de Multiseguros del Sur (seguros, Colombia). Responde SOLO JSON: {\"tipo_requerimiento\": \"siniestro|cotizacion|renovacion|consulta\", \"area\": \"siniestros|autos_nuevos|autos_renovaciones|generales|cumplimiento\", \"prioridad\": \"urgente|alta|normal|baja\", \"resumen\": \"max 140 chars\", \"confianza\": 0.0}. siniestro: choque, robo, dano, accidente -> area siniestros, urgente si ocurrio hoy o hay heridos. cotizacion de auto nuevo -> autos_nuevos. renovacion de poliza auto -> autos_renovaciones. polizas de hogar, vida, empresa -> generales. polizas de cumplimiento/contratos -> cumplimiento. Si dudas: consulta/generales/normal con confianza baja.";
return [{ json: {
  texto, chat_origen: String(m.chat.id), ref: 'tg-' + m.message_id,
  remitente: (m.from && (m.from.username || m.from.first_name)) || 'desconocido',
  oai_body: { model: 'gpt-4o-mini', temperature: 0,
    response_format: { type: 'json_object' },
    messages: [{ role: 'system', content: sys }, { role: 'user', content: texto }] }
} }];

const TIPOS = ['siniestro','cotizacion','renovacion','consulta'];
const AREAS = ['siniestros','autos_nuevos','autos_renovaciones','generales','cumplimiento'];
const PRIOS = ['urgente','alta','normal','baja'];
let r = {};
try { r = JSON.parse($json.choices[0].message.content); } catch (e) {}
const p = $('Preparar Clasificacion').first().json;
const texto = (p.texto || '').toLowerCase();
let tipo = TIPOS.includes(r.tipo_requerimiento) ? r.tipo_requerimiento : 'consulta';
let area = AREAS.includes(r.area) ? r.area : 'generales';
let prioridad = PRIOS.includes(r.prioridad) ? r.prioridad : 'normal';
let confianza = typeof r.confianza === 'number' ? r.confianza : 0;
// palabra clave dura (RIESGOS R2): senal de siniestro que GPT no clasifico
const kw = /(choqu|accident|rob(o|aron)|herid|colision|estrell)/;
let nota = confianza < 0.6 ? 'REVISAR: confianza baja (' + confianza + ')' : null;
if (kw.test(texto) && tipo !== 'siniestro') {
  tipo = 'siniestro'; area = 'siniestros'; prioridad = 'urgente';
  nota = 'REVISAR: forzado a siniestro por palabra clave';
}
return [{ json: { tipo, area, prioridad, confianza, nota,
  resumen: String(r.resumen || texto.slice(0, 140)),
  texto: p.texto, chat_origen: p.chat_origen, ref: p.ref, remitente: p.remitente } }];

const s = $input.first().json;
const alerta = (s && s.sla_alerta_minutos) || 240;
const escala = (s && s.sla_escalar_minutos) || 480;
const now = Date.now();
const v = $('Validar Clasificacion').first().json;
return [{ json: { ...v,
  sla_alerta_at: new Date(now + alerta * 60000).toISOString(),
  sla_escalar_at: new Date(now + escala * 60000).toISOString() } }];

const asesores = $input.all().map(i => i.json).filter(a => a && a.id !== undefined);
const v = $('Calcular SLA').first().json;
// preferir asesor con chat_id; si el area no tiene asesor -> supervisor queda a cargo via alerta
const a = asesores.find(x => x.telegram_chat_id) || asesores[0] || null;
const notas = [v.nota, a ? null : 'SIN ASESOR DE AREA - requiere asignacion manual'].filter(Boolean).join(' | ') || null;
return [{ json: { ...v, asesor_id: a ? a.id : null,
  asesor_nombre: a ? a.nombre : 'sin asignar',
  asesor_chat: a && a.telegram_chat_id ? String(a.telegram_chat_id) : '',
  caso_body: { canal_origen: 'telegram', tipo_requerimiento: v.tipo, area: v.area,
    estado: 'abierto', prioridad: v.prioridad, asesor_id: a ? a.id : null,
    sla_alerta_at: v.sla_alerta_at, sla_escalar_at: v.sla_escalar_at,
    ref_externa: v.ref, resumen: v.resumen, notas } } }];
